// вызвано в UI-потоке: планировщик поверх его SynchronizationContext
var ui = TaskScheduler.FromCurrentSynchronizationContext();

LoadAsync().ContinueWith(t =>
{
    status.Text = "Считаю…";          // ок: продолжение выполняется на ui
    t.ContinueWith(_ => Heavy());      // планировщик не указан → Current == ui
}, ui);                                //   → Heavy() в UI-потоке, окно висит

// StartNew: делегат, токен, флаги, планировщик
Task.Factory.StartNew(() => Heavy(), CancellationToken.None,
    TaskCreationOptions.None, TaskScheduler.Default);   // явно в пул

